// The collection: real suits from the Saraya range, each one shown on the house model ("Saanjh Model",
// an AI-generated character in Google Flow). Every picture was made from the suit's own reel on
// instagram.com/saraya_by_vanshie and checked against it (reel ids below, list in ai-model/ig/PROGRESS.md).
// Images: public/cat/<slug>/{front,front-cut}.webp, made by ai-model/import_ig.sh from ai-model/ig/out/<slug>.png.
//
// PRICES: not set yet (the owner decides later). `price: null` shows "Price on request" everywhere and turns the
// buy button into an enquiry. To add a price, put the NZ$ amount in `price` (e.g. price: 349). Nothing else changes.
// Descriptions say only what can be seen in the reel; fabric is left empty unless it is obvious (velvet, tissue).
import type { SpinSource } from '../fallback/spin';

export type Category = 'Sharara set' | 'Straight suit' | 'Farshi suit' | 'Anarkali' | 'Lehenga' | 'Drape set' | 'Long kurta set' | 'Co-ord set';
export type Occasion = 'Wedding guest' | 'Reception' | 'Sangeet' | 'Mehndi' | 'Diwali & Eid' | 'Festive';

export interface Piece {
  slug: string; name: string; category: Category; colour: string; swatch: string;
  occasions: Occasion[]; price: number | null; badge?: 'New in' | 'Heavy work';
  fabric?: string; craft: string[]; story: string; includes: string; care: string; leadTime: string;
  /** frontCut: the photo with the backdrop removed. back/detail are optional (most suits have one picture). */
  images: { front: string; frontCut: string; /** the cut-out at card size (750×1000), for small figures */ frontCutS?: string; back?: string; backCut?: string; detail?: string };
  spin?: SpinSource; glow: string;
  /** Instagram reel the suit comes from (for the owner; not shown on the site). */
  reel: string;
  /** Kept for older code paths; the new range has no meanings. */
  meaning?: string;
}

const img = (slug: string) => ({ front: `/cat/${slug}/front.webp`, frontCut: `/cat/${slug}/front-cut.webp`, frontCutS: `/cat/${slug}/front-cut-s.webp` });
const CARE = 'Dry clean recommended.';
const ASK = 'Ask us about sizes and delivery';

type Row = [slug: string, name: string, category: Category, colour: string, swatch: string, glow: string, occasions: Occasion[],
  craft: string[], includes: string, story: string, reel: string, extra?: Partial<Piece>];

