export const CATALOGUE: Piece[] = ROWS.map(([slug, name, category, colour, swatch, glow, occasions, craft, includes, story, reel, extra]) => ({
  slug, name, category, colour, swatch, glow, occasions, craft, includes, story, reel,
  price: null, care: CARE, leadTime: ASK, images: img(slug), ...extra,
}));

export const pieceBySlug = (s: string) => CATALOGUE.find((p) => p.slug === s);
export const CATEGORIES: Category[] = ['Farshi suit', 'Sharara set', 'Straight suit', 'Anarkali', 'Lehenga', 'Drape set', 'Long kurta set', 'Co-ord set'];
export const OCCASIONS: Occasion[] = ['Wedding guest', 'Reception', 'Sangeet', 'Mehndi', 'Diwali & Eid', 'Festive'];
/** Pieces in the hero line-up and the ceremonies walk come from the front of the list (heaviest work first). */
export const HERO = CATALOGUE.slice(0, 5);
